cat > /tmp/an/onecheck.py <<'EOF'
import pyarrow.parquet as pq, json, re, collections
t=pq.read_table('/workspace/taco_verl/train.parquet'); d=t.to_pydict()
def norm(s): return re.sub(r"\s+"," ",str(s)).strip()
one=[]
for i,e in enumerate(d['extra_info']):
    if e['n_tests']==1:
        g=json.loads(d['reward_model'][i]['ground_truth'])
        prompt=norm(d['prompt'][i][0]['content'])
        inp=g['inputs'][0]; out=g['outputs'][0]
        if isinstance(inp,list): inp="\n".join(inp)
        if isinstance(out,list): out="\n".join(out)
        one.append((i,norm(inp) in prompt, norm(out) in prompt, e['problem_id'], inp, out))
print('n one-test',len(one),'input in prompt',sum(x[1] for x in one),'output in prompt',sum(x[2] for x in one),'both',sum(x[1] and x[2] for x in one))
for x in one[:8]:
    print(x[3], 'input_in_prompt',x[1],'output_in_prompt',x[2],'inp',repr(x[4])[:80],'out',repr(x[5])[:60])
# find train7844
for i,e in enumerate(d['extra_info']):
    if e['problem_id']=='train7844':
        g=json.loads(d['reward_model'][i]['ground_truth'])
        print('--- train7844 prompt tail:',repr(d['prompt'][i][0]['content'][-400:]))
        print('inputs',json.dumps(g['inputs'])[:300]); print('outputs',json.dumps(g['outputs'])[:300]); print('n',e['n_tests'])
EOF
python3 -I /tmp/an/onecheck.py

