python -I - <<'PY'
import pyarrow.parquet as pq, json, glob, hashlib, collections
def qtext(s):
    i=s.find('QUESTION:\n'); j=s.rfind('\nANSWER:')
    return s[i+10:j] if i>=0 and j>i else None
def h(s): return hashlib.sha1(s.encode()).hexdigest()
tr=pq.read_table('taco_verl/train.parquet', columns=['prompt','extra_info']).to_pylist()
tm={}; ti={}
for r in tr:
    q=qtext('\n'.join(x['content'] for x in r['prompt'] if x['role']=='user'))
    if q: tm[h(q)]=r['extra_info']['problem_id']; ti[r['extra_info']['problem_id']]=r['extra_info']
mixed=collections.Counter(); pos=collections.Counter()
for f in sorted(glob.glob('rollout_data/*.jsonl'), key=lambda p:int(p.split('/')[-1].split('.')[0])):
    recs=[json.loads(l) for l in open(f)]
    for i in range(0,len(recs),8):
        g=recs[i:i+8]; ks=sum(1 for d in g if float(d['score'])>0)
        if ks>0:
            pid=tm.get(h(qtext(g[0]['input']))); n=ti.get(pid,{}).get('n_tests')
            b='1' if n==1 else '2-10' if n and n<=10 else '11-50' if n and n<=50 else '51-100' if n and n<=100 else '>100'
            mixed[b]+=1; pos[b]+=ks
print('mixed/nonzero-variance groups by n_tests',dict(mixed))
print('positives by n_tests',dict(pos))
PY

