import pyarrow.parquet as pq
def qtext(s):
    i=s.find('QUESTION:\n'); j=s.rfind('\nANSWER:')
    return s[i+10:j] if i>=0 and j>i else None
rows=pq.read_table('taco_verl/train.parquet',columns=['prompt','extra_info']).to_pylist()
has=set(); miss=[]
for r in rows:
    u='\n'.join(x['content'] for x in r['prompt'] if x['role']=='user'); q=qtext(u)
    pid=r['extra_info']['problem_id']
    if q: has.add(pid)
    else: miss.append((pid, r['extra_info'].get('n_tests'), len(u), u[:120]))
print('rows with qtext',len(has),'missing',len(miss))
print('missing pids that are also extracted?',sum(1 for p,_,_,_ in miss if p in has))
for x in miss[:3]: print(x)
